mapper.update:
update ssm_field_kpi_rel
set measure_code = #{metricCode}
where measure_code in
(
    #{code}
)

mapper.select:
select concat(t.table_schema,'.',t.table_name) from ssd_table_def t
where
 t.table_id = #{tableId}

mapper.update:
update ssd_field_def t
set
t.is_active = #{isActive}
where
t.`dim_table_id` = #{id}
OR t.`fct_table_id` =  #{id}

mapper.select:
SELECT t.field_id AS id, t.field_code AS `code`, t.field_name AS `name`, t.field_title AS title, front.ctg_id AS categoryId, front.`ctg_name` AS categoryName, back.ctg_id AS virtualCategoryId, back.`ctg_name` AS virtualCategoryName, t.is_sensitive AS isSensitive, t.is_active AS isActive FROM ssd_field_def t LEFT JOIN ( SELECT k1.`field_id`, GROUP_CONCAT(k1.`ctg_id`) AS ctg_id, GROUP_CONCAT(k2.`ctg_name_path`) AS ctg_name FROM `ssm_field_ctg_rel` k1 INNER JOIN `v_ssd_field_ctg` k2 ON k1.`ctg_id` = k2.`ctg_id` AND k1.`ctg_type` = 'front' WHERE k2.`is_active` = 1 GROUP BY k1.`field_id` ) front ON t.`field_id` = front.`field_id` LEFT JOIN ( SELECT k1.`field_id`, GROUP_CONCAT(k1.`ctg_id`) AS ctg_id, GROUP_CONCAT(k2.`ctg_name_path`) AS ctg_name FROM `ssm_field_ctg_rel` k1 INNER JOIN v_ssd_field_ctg k2 ON k1.`ctg_id` = k2.`ctg_id` AND k1.`ctg_type` = 'back' WHERE k2.`is_active` = 1 GROUP BY k1.`field_id` ) back ON t.`field_id` = back.`field_id` WHERE 1=1
and t.is_sensitive = #{isSensitive}
ORDER BY front.ctg_id

